var page = readFile(arguments[0]);
var dataOpen = '<script type="application/json" id="round-data">';
var dataStart = page.indexOf(dataOpen) + dataOpen.length;
var dataEnd = page.indexOf("</script>", dataStart);
var codeStart = page.indexOf(">", page.indexOf("<script nonce=", dataEnd)) + 1;
var code = page.slice(codeStart, page.indexOf("</script>", codeStart));

function Node(tag) { this.tag = tag; this.children = []; this.listeners = {}; this.textContent = ""; }
Node.prototype.appendChild = function (child) { this.children.push(child); return child; };
Node.prototype.addEventListener = function (type, fn) { (this.listeners[type] = this.listeners[type] || []).push(fn); };
Node.prototype.setAttribute = function () {};
Node.prototype.focus = function () {};
Node.prototype.select = function () {};
Node.prototype.fire = function (type) { (this.listeners[type] || []).forEach(function (fn) { fn(); }); };
function walk(node, visit) { visit(node); (node.children || []).forEach(function (child) { walk(child, visit); }); }

var ids = { "round-data": new Node("script"), "app": new Node("main"), "verdict-box": new Node("textarea"),
  "copy-status": new Node("span"), "copy-all": new Node("button") };
ids["round-data"].textContent = page.slice(dataStart, dataEnd);
var document = {
  getElementById: function (id) { return ids[id]; },
  createElement: function (tag) { return new Node(tag); },
  createTextNode: function (text) { var node = new Node("#text"); node.textContent = text; return node; },
  execCommand: function () { return true; }
};
var navigator = {};
if (typeof URL === "undefined") {
  var URL = function (address) {
    var match = /^([a-z][a-z0-9+.-]*:)\/\/[^\s]+$/i.exec(address);
    if (!match) { throw new Error("bad address"); }
    this.protocol = match[1].toLowerCase();
  };
}

(0, eval)(code); // the page's own script, read from the file built in this directory

var text = [], links = [], radios = [], inputs = [];
walk(ids.app, function (node) {
  if (node.textContent) { text.push(node.textContent); }
  if (node.tag === "a") { links.push(node.href + " rel=" + node.rel); }
  if (node.tag === "input" && node.type === "radio") { radios.push(node); }
  if (node.tag === "input" && node.type === "text") { inputs.push(node); }
});
var all = text.join("\n");
function expect(label, ok) { print((ok ? "ok   " : "FAIL ") + label); if (!ok) { failed = true; } }
var failed = false;
var cards = ids.app.children.filter(function (node) { return node.className === "card"; });
expect("four cards", cards.length === 4);
